def runs(line):
    n=len(line); res=[]; j=0
    while j<n:
        if line[j]:
            c=line[j]; s=j
            while j<n and line[j]==c: j+=1
            res.append((c,s,j-s))
        else: j+=1
    return res

def solve_variant(g, mode, porder):
    h=len(g); w=len(g[0]); o=[[0]*w for _ in range(h)]
    # horizontal segments per row
    hsegs=[]  # (row, color, c0, c1)
    for r in range(h):
        for c,s,L in runs(g[r]):
            hsegs.append((r,c,s,s+L-1))
    vseg=set()
    for c in range(w):
        col=[g[r][c] for r in range(h)]
        for cc,s,L in runs(col):
            vseg.add((c,cc,s,s+L-1))
    # paint order list
    order=porder(g)
    # paints: each produces a set of (r,c) cells; conflicts by order
    def ext(seg,mode):
        c,cc,a,b=seg
        cells=set()
        if mode=='H':
            for j in range(a,b+1):
                cells.add((a,j))
        else:
            for i in range(a,b+1):
                cells.add((i,c))
        return cells
    allpats=[]
    for typ,seg in zip(['H']*len(hsegs)+['V']*len(vseg), hsegs+vseg):
        allpats.append((typ,seg))
    results={}
    for idx,(typ,seg) in enumerate(allpats):
        cells=ext(seg,typ)
        for r,c in cells:
            if (r,c) not in results or idx>results[(r,c)][0]:
                results[(r,c)]=(idx,seg)
    for (r,c),(idx,seg) in results.items():
        o[r][c]=seg[1]
    return o

def firstscan(g):
    # scan order: by first appearance row-major of color
    seen={}
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]: seen.setdefault(g[r][c],[]).append((r,c))
    ordl=[list(k) for k in sorted(seen.items(), key=lambda kv:min(kv[1][0]*100+kv[1][1]))]
    res=[]
    for col,_ in ordl:
        for r,c in sorted(seen[col]):
            typ='V' if sum(1 for rr in range(len(g)) if g[rr][c]==col)>1 else ('H' if sum(1 for cc in range(len(g[0])) if g[r][cc]==col)>1 else 'X')
            if typ=='X': continue
            if typ=='V': res.append(('V',(c,col,r,min(rr for rr in range(len(g)) if g[rr][c]==col),max(rr for rr in range(len(g)) if g[rr][c]==col))))
            else: res.append(('H',(r,col,min(cc for cc in range(len(g[0])) if g[r][cc]==col),max(cc for cc in range(len(g[0])) if g[r][cc]==col))))
    return res

for name,po in [('firstscan',[('H',lambda s:s[1]),('V',lambda s:s[1])]),('lenbig',lambda s:-s[1])]:
