def f(g):
    h=len(g); w=len(g[0]); o=[[0]*w for _ in range(h)]
    # 1. fill horizontal gaps per row per color
    for i in range(h):
        row=g[i]; cur=None
        for j in range(w):
            v=row[j]
            if v==0: continue
            if cur is not None and v==cur:
                pass
            elif cur is not None and v!=cur:
                # gap between cur run end (j-1) and new run start (j)
                for k in range(cur+1, j): o[i][k]=cur
            cur=v
        if cur is not None:
            for k in range(cur+1, w): o[i][k]=cur
    # 2. vertical extension until blocked by different color
    for j in range(w):
        col=[g[i][j] for i in range(h)]
        segs=[]; cur=col[0]; s=0
        for i in range(1,h):
            if col[i]==cur: continue
            segs.append((cur,s,i-1)); cur=col[i]; s=i
        segs.append((cur,s,h-1))
        for c_,a,b in segs:
            # extend up
            r=a
            while r-1>=0 and col[r-1]==0:
                r-=1
            for k in range(r,a): o[k][j]=c_
            # extend down
            r=b
            while r+1<h and col[r+1]==0:
                r+=1
            for k in range(b,r+1): o[k][j]=c_
    return o
