def solve(gi):
    H=len(gi); W=len(gi[0]); g=[r[:] for r in gi]
    changed=True
    while changed:
        changed=False
        # horizontal runs: fill gaps in their row, then grow up column-wise
        for i in range(H):
            j=0
            while j<W:
                if g[i][j]==0: j+=1; continue
                c=g[i][j]; start=j
                while j<W and g[i][j]==c: j+=1
                end=j-1
                # fill gap between same-color cells in this row
                k=start
                while k<end:
                    if g[i][k]==0: g[i][k]=c; changed=True
                    k+=1
        for j in range(W):
            i=0
            while i<H:
                if g[i][j]==0: i+=1; continue
                c=g[i][j]; start=i
                while i<H and g[i][j]==c: i+=1
                end=i-1
                k=start
                while k<end:
                    if g[k][j]==0: g[k][j]=c; changed=True
                    k+=1
        # now grow each color up
        for j in range(W):
            i=H-1
            while i>=0:
                if g[i][j]!=0:
                    i-=1; continue
                # look down for support
                below=i+1
                if below<H and g[below][j]!=0:
                    g[i][j]=g[below][j]; changed=True
                i-=1
        for i in range(H):
            j=W-1
            while j>=0:
                if g[i][j]!=0: j-=1; continue
                left=j+1
                if left<W and g[i][left]!=0:
                    g[i][j]=g[i][left]; changed=True
                j-=1
    return g
