def bbox(inp):
    H=len(inp);W=len(inp[0])
    rs=[i for i,r in enumerate(inp) if any(c for c in r)]; cs=[j for r in inp for j,c in enumerate(r) if c]
    return min(rs),max(rs),min(cs),max(cs)
def tile(inp):
    r0,r1,c0,c1=bbox(inp);H,Wb=len(inp),len(inp[0])
    P=[row[c0:c1+1] for row in inp[r0:r1+1]]
    ph,pw=len(P),len(P[0])
    out=[[0]*Wb for _ in range(H)]
    for i in range(H):
        for j in range(Wb):
            out[i][j]=P[(i-r0)%ph][(j-c0)%pw]
    return out
